#!/bin/bash
whois "$1" | awk -F': +' 'BEGIN{split("Registrant Name,Registrant Organization,Registrant Street,Registrant City,Registrant State/Province,Registrant Postal Code,Registrant Country,Registrant Phone,Registrant Phone Ext,Registrant Fax,Registrant Fax Ext,Registrant Email,Admin Name,Admin Organization,Admin Street,Admin City,Admin State/Province,Admin Postal Code,Admin Country,Admin Phone,Admin Phone Ext,Admin Fax,Admin Fax Ext,Admin Email,Tech Name,Tech Organization,Tech Street,Tech City,Tech State/Province,Tech Postal Code,Tech Country,Tech Phone,Tech Phone Ext,Tech Fax,Tech Fax Ext,Tech Email",o,",")}{gsub(/\r/,"");for(i=1;i<=2;i++){sub(/^ +/,"",$i);sub(/ +$/,"",$i)}if($1!="")v[$1]=$2}END{for(i=1;i<=36;i++){f=o[i];val=v[f];if(f~/Street$/&&val!="")val=val" ";if(f~/Ext$/)f=f":";printf "%s,%s%s",f,val,(i==36?"":"\n")}'
